1	// POST /groups/:id/import: records a list of expenses and payments for a group in one write, all or nothing.
2	// Same handler contract as lib/groups.mjs: it returns the new store as `state` instead of changing the old one.
3	import { NOT_FOUND, findGroup } from './groups.mjs'
4	import { balances, expenseView, paymentView } from './ledger.mjs'
5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
6	
7	const MAX_ENTRIES = 50
8	// parseMember wants a message; check() swaps it for the rule name, so these only keep the POST routes' wording.
9	const PAYER_MESSAGE = 'payer must be a member of the group'
10	const MEMBER_MESSAGE = 'from and to must be two different members of the group'
11	const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
12	const ENTRY_FIELDS = {
13	  expense: ['type', 'description', 'payer', 'amount', 'split'],
14	  payment: ['type', 'from', 'to', 'amount'],
15	}
16	
17	// Thrown by the entry checks with the name of the rule the entry breaks.
18	class RuleError extends Error {}
19	
20	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
21	
22	// Runs parse and returns its value; a ValidationError becomes the given rule.
23	function check(rule, parse) {
24	  try {
25	    return parse()
26	  } catch (err) {
27	    if (err instanceof ValidationError) throw new RuleError(rule)
28	    throw err
29	  }
30	}
31	
32	// A flag that is false when its key is absent, and must be a boolean when present.
33	function parseFlag(body, name) {
34	  if (!Object.hasOwn(body, name)) return false
35	  if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
36	  return body[name]
37	}
38	
39	// The body's checks, in the order the first failing one decides the 400 message.
40	function parseBody(body) {
41	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
42	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
43	  const { entries } = body
44	  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
45	    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
46	  }
47	  return { entries, dryRun: parseFlag(body, 'dry_run'), skipRecorded: parseFlag(body, 'skip_recorded') }
48	}
49	
50	// The clean { type, fields } of one entry, or a RuleError naming the first rule it breaks before `duplicate`.
51	function parseEntry(entry, group) {
52	  if (!isObject(entry)) throw new RuleError('not-an-object')
53	  const { type } = entry
54	  if (type !== 'expense' && type !== 'payment') throw new RuleError('bad-type')
55	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[type].includes(key))) throw new RuleError('unknown-field')
56	  if (type === 'expense') {
57	    return {
58	      type,
59	      fields: {
60	        description: check('bad-description', () => parseDescription(entry.description)),
61	        payer: check('bad-payer', () => parseMember(entry.payer, group.members, PAYER_MESSAGE)),
62	        amount: check('bad-amount', () => parseAmount(entry.amount)),
63	        split: check('bad-split', () => parseSplit(entry.split, group.members)),
64	      },
65	    }
66	  }
67	  const from = check('bad-from', () => parseMember(entry.from, group.members, MEMBER_MESSAGE))
68	  const to = check('bad-to', () => parseMember(entry.to, group.members, MEMBER_MESSAGE))
69	  if (to === from) throw new RuleError('bad-to')
70	  return { type, fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
71	}
72	
73	// Two expenses are the same when payer, amount in cents and trimmed, lower-cased description match.
74	const expenseKey = ({ payer, amount, description }) =>
75	  JSON.stringify([payer, amount, description.trim().toLowerCase()])
76	
77	// Sorts the entries into { problems, skipped, accepted }: one problem per entry that breaks a rule, the indexes
78	// of the already-recorded entries skip_recorded leaves out, and the parsed entries to import, all in entry order.
79	function sortEntries(state, group, entries, skipRecorded) {
80	  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
81	  // Every expense that passed its field checks, so a later copy is a duplicate even of a skipped one.
82	  const seen = new Set()
83	  const problems = []
84	  const skipped = []
85	  const accepted = []
86	  for (const [index, entry] of entries.entries()) {
87	    let parsed
88	    try {
89	      parsed = parseEntry(entry, group)
90	    } catch (err) {
91	      if (!(err instanceof RuleError)) throw err
92	      problems.push({ index, rule: err.message })
93	      continue
94	    }
95	    if (parsed.type === 'expense') {
96	      const key = expenseKey(parsed.fields)
97	      const isDuplicate = seen.has(key)
98	      seen.add(key)
99	      if (isDuplicate) {
100	        problems.push({ index, rule: 'duplicate' })
101	        continue
102	      }
103	      if (recorded.has(key)) {
104	        if (skipRecorded) skipped.push(index)
105	        else problems.push({ index, rule: 'already-recorded' })
106	        continue
107	      }
108	    }
109	    accepted.push(parsed)
110	  }
111	  return { problems, skipped, accepted }
112	}
113	
114	// The store with the accepted entries added, each kind numbered on from its next id in entry order.
115	function addEntries(state, group, accepted) {
116	  let { nextExpenseId, nextPaymentId } = state
117	  const expenses = []
118	  const payments = []
119	  for (const { type, fields } of accepted) {
120	    if (type === 'expense') expenses.push({ id: nextExpenseId++, group: group.id, ...fields })
121	    else payments.push({ id: nextPaymentId++, group: group.id, ...fields })
122	  }
123	  const next = {
124	    ...state,
125	    expenses: [...state.expenses, ...expenses],
126	    payments: [...state.payments, ...payments],
127	    nextExpenseId,
128	    nextPaymentId,
129	  }
130	  return { expenses, payments, next }
131	}
132	
133	export function importEntries({ state, params, body }) {
134	  const group = findGroup(state, params[0])
135	  if (!group) return NOT_FOUND
136	  const { entries, dryRun, skipRecorded } = parseBody(body)
137	  const { problems, skipped, accepted } = sortEntries(state, group, entries, skipRecorded)
138	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
139	
140	  const { expenses, payments, next } = addEntries(state, group, accepted)
141	  const reply = {
142	    expenses: expenses.map(expenseView),
143	    payments: payments.map(paymentView),
144	    skipped,
145	    balances: balances(next, group),
146	  }
147	  if (dryRun) return { status: 200, body: reply }
148	  // Nothing to record (every entry skipped): reply as a success but leave the data file alone.
149	  return { status: 201, body: reply, ...(accepted.length > 0 && { state: next }) }
150	}
