test('amounts like 4.35 come back exactly, and uneven splits add up over HTTP', () => withApp(async call => {
  await call('POST', '/groups', trip)
  const post = body => call('POST', '/groups/trip/expenses', body)
  const coffee = await post({ description: 'Coffee', payer: 'Ben', amount: 4.35 })
  assert.equal(coffee.status, 201)
  assert.equal(coffee.body.amount, 4.35)
  assert.deepEqual(coffee.body.shares, { Ann: 1.45, Ben: 1.45, Cara: 1.45 })
  const gum = await post({ description: 'Gum', payer: 'Ann', amount: 0.29 })
  assert.deepEqual(gum.body.shares, { Ann: 0.1, Ben: 0.1, Cara: 0.09 })
  const bus = await post({ description: 'Bus', payer: 'Cara', amount: 1.15, split: ['Cara', 'Ann'] })
  assert.deepEqual(bus.body.shares, { Cara: 0.58, Ann: 0.57 })
  const taxi = await post({ description: 'Taxi', payer: 'Ann', amount: 10 })
  assert.deepEqual(taxi.body.shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 })
  const list = await call('GET', '/groups/trip/expenses')
  assert.deepEqual(list.body.expenses.map(e => e.amount), [4.35, 0.29, 1.15, 10])
  const bal = await call('GET', '/groups/trip/balances')
  assert.deepEqual(bal.body, { balances: { Ann: 4.83, Ben: -0.53, Cara: -4.3 } })
  const patched = await call('PATCH', '/groups/trip/expenses/2', { amount: 4.35 })
  assert.equal(patched.status, 200)
  assert.equal(patched.body.amount, 4.35)
}))

